import {apiRequest,baseUrl,supabase} from './api';
import React,{useState,useEffect,useMemo,useCallback,useRef,createContext,useContext} from 'react';
import {LayoutDashboard,Users,UsersRound,ClipboardList,FileDown,Settings2,History,Upload,ShieldCheck,ChevronRight,ChevronDown,Menu,X,Search,Plus,ArrowUpRight,ArrowRight,Check,CheckCheck,AlertCircle,MessageSquare,LockKeyhole,UnlockKeyhole,Download,RefreshCw,CalendarDays,Clock3,BookOpen,Activity,MoreHorizontal,Pencil,Send,Eye,CheckCircle2,FolderOpen,LogOut,Archive,Filter,Database,LoaderCircle,Info,Target,UserRound,Bell,SquarePen,Paperclip,ChevronLeft} from 'lucide-react';
import {ResponsiveContainer,AreaChart,Area,XAxis,YAxis,CartesianGrid,Tooltip,BarChart,Bar,PieChart,Pie,Cell} from 'recharts';
import {Row,MONTHS,PERMISSIONS,parseJSON,currentMonth,today,serviceYear,serviceMonths,monthName,valueAt,can,computeDashboard,DEFAULT_TYPES} from '../lib/domain';
import {readExcel} from '../lib/importer';
import {generateS21,exportPdfs,saveDownload,folderFor} from '../lib/pdf';

const Context=createContext<any>(null);const useApp=()=>useContext(Context);
const nf=(x:any)=>new Intl.NumberFormat('es-PE',{maximumFractionDigits:1}).format(Number(x||0));
const initials=(name:string)=>name.split(/[ @]/).filter(Boolean).slice(0,2).map(n=>n[0]).join('').toUpperCase();
const labelDate=(s:string)=>s?new Date(s.length===10?s+'T12:00:00Z':s).toLocaleDateString('es-PE',{timeZone:'America/Lima'}):'Sin dato';
const NAV=[{id:'dashboard',name:'Dashboard',icon:LayoutDashboard,permission:'dashboard',section:'PRINCIPAL'},{id:'reports',name:'Recepción de informes',icon:ClipboardList,permission:'reports.write'},{id:'export',name:'Registros S-21',icon:FileDown,permission:'pdf.single'},{id:'review',name:'Revisión y correcciones',icon:MessageSquare,permission:'reports.correct'},{id:'publishers',name:'Publicadores',icon:Users,permission:'masters.read',section:'MAESTROS'},{id:'groups',name:'Grupos',icon:UsersRound,permission:'masters.read'},{id:'types',name:'Tipos de predicación',icon:BookOpen,permission:'masters.read'},{id:'assignments',name:'Vigencias y campañas',icon:CalendarDays,permission:'assignments.write'},{id:'catalogs',name:'Clasificaciones y estados',icon:Settings2,permission:'catalogs.write'},{id:'users',name:'Usuarios y perfiles',icon:ShieldCheck,permission:'users.write',section:'ADMINISTRACIÓN'},{id:'import',name:'Importación y respaldos',icon:Upload,permission:'import'},{id:'audit',name:'Historial de cambios',icon:History,permission:'audit'}];
function Badge({children,tone='neutral'}:{children:React.ReactNode,tone?:string}){return <span className={`badge ${tone}`}>{children}</span>;}
function Button({children,onClick,primary=false,disabled=false,small=false,type='button'}:any){return <button type={type} className={`button ${primary?'primary':''} ${small?'small':''}`} onClick={onClick} disabled={disabled}>{children}</button>;}
function Empty({title='Todavía no hay registros',text='Los datos aparecerán aquí cuando los registres.',children}:any){return <div className="empty"><FolderOpen size={32}/><h3>{title}</h3><p>{text}</p>{children}</div>;}
function Table({headers,children}:any){return <div className="table-wrap"><table><thead><tr>{headers.map((h:any,i:number)=><th key={i}>{h}</th>)}</tr></thead><tbody>{children}</tbody></table></div>;}
function Avatar({name,size=''}:any){return <span className={`avatar ${size}`}>{initials(name||'?')}</span>;}
function Person({p,onClick}:any){return <button className="person" onClick={onClick}><Avatar name={p.alias}/><span><strong>{p.alias}</strong><small>{p.code}</small></span></button>;}
function Field({label,children,hint}:any){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>;}

export default function App(){
 const [data,setData]=useState<Row|null>(null),[page,setPage]=useState('dashboard'),[mobile,setMobile]=useState(false),[collapsed,setCollapsed]=useState(false),[dialog,setDialog]=useState<Row|null>(null),[toast,setToast]=useState<Row|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[dirty,setDirty]=useState(false);
 const [filters,setFilters]=useState<Row>({year:serviceYear(currentMonth()),month:'',group:'',person:'',cutoff:today()});const first=useRef(true);
 const notify=useCallback((message:string,type='success')=>{setToast({message,type});setTimeout(()=>setToast(null),6500);},[]);
 const refresh=useCallback(async()=>{try{const d=await apiRequest('state') as Row;setData(d);setError('');if(first.current){first.current=false;if(!can(d.actor,'dashboard'))setPage(can(d.actor,'reports.write')?'reports':'publishers');}}catch(e:any){setError(e.message);}},[]);
 useEffect(()=>{refresh();},[refresh]);
 useEffect(()=>{const handler=()=>{if(!dirty&&!dialog)refresh();};window.addEventListener('focus',handler);const timer=setInterval(handler,60000);return()=>{window.removeEventListener('focus',handler);clearInterval(timer);};},[refresh,dirty,dialog]);
 const request=useCallback(async(body:Row,path='/api/mutate')=>{return await apiRequest(path,body);},[]);
 const mutate=useCallback(async(body:Row,message='Cambios guardados')=>{setBusy(true);try{const r=await request(body);await refresh();notify(message);return r;}catch(e:any){notify(e.message,'error');throw e;}finally{setBusy(false);}},[request,refresh,notify]);
 const go=(id:string)=>{if(dirty&&!window.confirm('Hay cambios sin guardar. ¿Deseas salir de esta pantalla?'))return;setPage(id);setMobile(false);setDirty(false);};
 const ctx={data,filters,setFilters,page,go,dialog,setDialog,notify,request,mutate,refresh,busy,setBusy,setDirty};
 if(!data)return <main className="loading-page"><img src={`${baseUrl}favicon.svg`} width="60" alt="S-21"/><h2>S-21 Monterrico</h2>{error?<><p>{error}</p><Button onClick={refresh}><RefreshCw size={16}/> Reintentar</Button></>:<><LoaderCircle className="spin"/><p>Preparando tu espacio de trabajo…</p></>}</main>;
 const available=NAV.filter(n=>can(data.actor,n.permission)),nav=available.find(n=>n.id===page)||available[0];
 return <Context.Provider value={ctx}><div className={`app-shell ${collapsed?'compact':''}`}>
  {mobile&&<button className="mobile-backdrop" aria-label="Cerrar menú" onClick={()=>setMobile(false)}/>}
  <aside className={`sidebar ${mobile?'open':''}`}><a className="brand" href={baseUrl} aria-label="S-21 Monterrico"><img src={`${baseUrl}favicon.svg`} alt="Logo S-21"/><span><b>S-21</b><small>MONTERRICO</small></span></a><div className="workspace-tag"><span className="dot"/> Gestión congregacional</div>
  <nav>{available.map(n=><React.Fragment key={n.id}>{n.section&&<div className="nav-section">{n.section}</div>}<button className={`nav-item ${page===n.id?'selected':''}`} onClick={()=>go(n.id)} title={n.name}><n.icon size={18}/><span>{n.name}</span>{n.id==='review'&&(data.corrections.filter((x:Row)=>x.state==='pending').length+data.issues.filter((x:Row)=>x.state==='pending').length>0)&&<i>{data.corrections.filter((x:Row)=>x.state==='pending').length+data.issues.filter((x:Row)=>x.state==='pending').length}</i>}</button></React.Fragment>)}</nav>
  <div className="sidebar-bottom"><div className="year-tile"><CalendarDays size={19}/><div><small>AÑO DE SERVICIO</small><b>{filters.year}</b></div><span>SEP — AGO</span></div><button className="collapse-button" onClick={()=>setCollapsed(!collapsed)}><ChevronLeft size={16}/><span>Contraer menú</span></button><div className="side-user"><Avatar name={data.actor.name}/><span><strong>{data.actor.name}</strong><small>{data.actor.profile_name}</small></span><button aria-label="Cerrar sesión" onClick={async()=>{await supabase.auth.signOut();}}><LogOut size={16}/></button></div></div></aside>
  <div className="workspace"><header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" aria-label="Abrir menú" onClick={()=>setMobile(true)}><Menu size={21}/></button><span>Monterrico</span><ChevronRight size={14}/><strong>{nav?.name}</strong></div><div className="topbar-right"><span className="synced"><span className="dot"/> Datos sincronizados</span><button className="icon-button" title="Actualizar datos" onClick={()=>{refresh();notify('Datos actualizados');}}><RefreshCw size={17}/></button><Avatar name={data.actor.name}/></div></header>
  <main className="main-content">{error&&<div className="notice error"><AlertCircle size={16}/>{error}</div>}<div className="page-heading"><div><span className="eyebrow">{['dashboard','reports','export','review'].includes(page)?'CONTROL Y SEGUIMIENTO':'ADMINISTRACIÓN'}</span><h1>{page==='dashboard'?'Dashboard general':nav?.name}</h1><p>{{dashboard:'Una visión clara de la participación y el avance de la congregación.',reports:'Recoge y envía los informes mensuales de cada grupo.',export:'Prepara los registros de cada hermano con el formato S-21.',review:'Revisa solicitudes, datos pendientes y versiones de un mismo mes.',publishers:'Toda la información de los hermanos, en un solo lugar.',groups:'Organiza integrantes, encargados y auxiliares.',types:'Metas y configuraciones con vigencia mensual.',assignments:'Cada responsabilidad conserva su historia.',catalogs:'Clasificaciones, estados y condiciones administrables.',users:'Accesos y permisos para cada responsabilidad.',import:'Migra información y conserva respaldos de los datos.',audit:'Trazabilidad de las operaciones realizadas.'}[page]}</p></div><div className="heading-actions">{page==='dashboard'&&can(data.actor,'pdf.bulk')&&<Button onClick={()=>go('export')}><Download size={16}/> Exportar S-21</Button>}{page==='publishers'&&can(data.actor,'publishers.write')&&<Button primary onClick={()=>setDialog({kind:'form',entity:'publisher'})}><Plus size={17}/> Nuevo publicador</Button>}{page==='groups'&&can(data.actor,'groups.write')&&<Button primary onClick={()=>setDialog({kind:'form',entity:'group'})}><Plus size={17}/> Nuevo grupo</Button>}</div></div>
  {page==='dashboard'?<Dashboard/>:page==='reports'?<Reports/>:page==='publishers'?<Publishers/>:page==='groups'?<Groups/>:page==='types'?<Types/>:page==='assignments'?<Assignments/>:page==='catalogs'?<Catalogs/>:page==='export'?<Exports/>:page==='review'?<Review/>:page==='users'?<UsersPage/>:page==='import'?<Imports/>:page==='audit'?<Audit/>:null}
  <footer className="footer"><span>S-21 Monterrico <span>·</span> Gestión de publicadores e informes</span><span><LockKeyhole size={12}/> Espacio privado</span></footer></main></div>
  {dialog&&<Dialog/>}{toast&&<div className={`toast ${toast.type}`} role="status">{toast.type==='error'?<AlertCircle size={18}/>:<CheckCircle2 size={18}/>}<span>{toast.message}</span><button aria-label="Cerrar aviso" onClick={()=>setToast(null)}><X size={16}/></button></div>}
 </div></Context.Provider>;
}

function Filters(){const{data,filters:f,setFilters}=useApp();const years=[...new Set([serviceYear(currentMonth()),...data.reports.map((r:Row)=>serviceYear(r.month))])].sort((a:any,b:any)=>b-a) as number[];const change=(key:string,v:any)=>setFilters((x:Row)=>({...x,[key]:v,...(key==='year'?{month:'',person:''}:key==='group'?{person:''}:{})}));return <div className="filters panel"><div className="filter-label"><Filter size={17}/><span>Filtros</span></div><Field label="Año de servicio"><select value={f.year} onChange={e=>change('year',Number(e.target.value))}>{years.map(y=><option key={y} value={y}>{y} · Sep {y-1} – Ago {y}</option>)}</select></Field><Field label="Mes"><select value={f.month} onChange={e=>change('month',e.target.value)}><option value="">Todos los meses</option>{serviceMonths(Number(f.year)).map((m,i)=><option key={m} value={m}>{MONTHS[i]} {m.slice(0,4)}</option>)}</select></Field><Field label="Grupo"><select value={f.group} onChange={e=>change('group',e.target.value)}><option value="">Todos los grupos</option>{data.groups.map((g:Row)=><option key={g.id} value={g.id}>{g.name}</option>)}</select></Field><Field label="Publicador"><select value={f.person} onChange={e=>change('person',e.target.value)}><option value="">Todos los publicadores</option>{data.publishers.filter((p:Row)=>!f.group||p.group_id===f.group).sort((a:Row,b:Row)=>a.alias.localeCompare(b.alias)).map((p:Row)=><option key={p.id} value={p.id}>{p.alias}</option>)}</select></Field></div>;}

function Dashboard(){const{data,filters,setDialog,go}=useApp(),d=useMemo(()=>computeDashboard(data,filters),[data,filters]);const groupData=data.groups.filter((g:Row)=>!filters.group||g.id===filters.group).map((g:Row)=>{const rs=d.reportList.filter((r:Row)=>r.group_id===g.id&&r.state!=='draft');return{name:g.name,SI:rs.filter((r:Row)=>r.participation==='SI').length,NO:rs.filter((r:Row)=>r.participation==='NO').length,received:rs.length};});const metrics=[{title:'Personas bajo seguimiento',value:d.total,icon:Users,sub:'Activos + inactivos + expulsados',color:'orange'},{title:'Publicadores activos',value:d.active,icon:Activity,sub:'Según el estado del padrón',color:'green'},{title:'Publicadores inactivos',value:d.inactive,icon:Clock3,sub:'Conservan su registro e historial',color:'amber'},{title:'Expulsados',value:d.expelled,icon:Archive,sub:'Seguimiento separado del estado activo',color:'slate'}];
 return <><Filters/><div className="period-strip"><span><CalendarDays size={14}/> Año de servicio {filters.year} <i>·</i> {filters.month?monthName(filters.month):`Septiembre ${filters.year-1} – Agosto ${filters.year}`}</span><span>Corte: {labelDate(filters.cutoff)}</span></div><div className="metrics-grid">{metrics.map(m=><div className="metric panel" key={m.title}><div className="metric-top"><span>{m.title}</span><span className={`metric-icon ${m.color}`}><m.icon size={18}/></span></div><strong>{nf(m.value)}</strong><small>{m.sub}</small></div>)}</div>
 <div className="insight-grid"><div className="panel chart-panel"><div className="panel-heading"><div><h2>Participación en el ministerio</h2><p>Informes recibidos por grupo en el período seleccionado</p></div><div className="legend"><span><i className="orange-dot"/> Participó</span><span><i className="gray-dot"/> No participó</span></div></div><div className="chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={groupData} barSize={30}><CartesianGrid strokeDasharray="3 4" vertical={false} stroke="#eeeae5"/><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize:11,fill:'#7d817f'}}/><YAxis axisLine={false} tickLine={false} tick={{fontSize:11,fill:'#999'}}/><Tooltip cursor={{fill:'#fff8ef'}}/><Bar dataKey="SI" name="Participó" stackId="a" fill="#ef762e" radius={[0,0,0,0]}/><Bar dataKey="NO" name="No participó" stackId="a" fill="#e8e8e5" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div><div className="chart-foot"><span><b>{nf(d.uniqueParticipants)}</b> personas únicas participaron</span><span>{nf(d.participation)}% de informes recibidos</span></div></div>
 <div className="panel reception-card"><div className="panel-heading"><div><h2>Recepción de informes</h2><p>Seguimiento del período</p></div><ClipboardList size={19}/></div><div className="donut-box"><ResponsiveContainer width="100%" height={190}><PieChart><Pie data={[{name:'Recibidos',value:d.received},{name:'Pendientes',value:d.pending}]} innerRadius={63} outerRadius={78} startAngle={90} endAngle={-270} paddingAngle={3} dataKey="value" stroke="none"><Cell fill="#ef762e"/><Cell fill="#f2eee8"/></Pie></PieChart></ResponsiveContainer><div className="donut-label"><strong>{nf(d.coverage)}<small>%</small></strong><span>de cobertura</span></div></div><div className="reception-stats"><span><i className="orange-dot"/> Recibidos <b>{nf(d.received)}</b></span><span><i className="gray-dot"/> Pendientes <b>{nf(d.pending)}</b></span></div><button className="text-button" onClick={()=>go('reports')}>Ir a recepción de informes <ArrowRight size={15}/></button></div></div>
 <div className="secondary-grid"><div className="panel mini-stat"><span className="metric-icon orange"><BookOpen size={19}/></span><div><span>{filters.month?'Cursos bíblicos reportados':'Cursos-mes reportados'}</span><strong>{nf(d.courses)}</strong><small>{filters.month?'Suma de los informes del mes':'Acumulado de reportes mensuales; no estudiantes únicos'}</small></div></div><div className="panel mini-stat"><span className="metric-icon amber"><Clock3 size={19}/></span><div><span>Horas contabilizables</span><strong>{nf(d.hours)} <small>h</small></strong><small>Según el tipo de predicación de cada mes</small></div></div><div className="panel mini-stat"><span className="metric-icon green"><CheckCheck size={19}/></span><div><span>Participaciones registradas</span><strong>{nf(d.yes)}</strong><small>{nf(d.no)} con respuesta NO · pendientes por separado</small></div></div></div>
 <div className="panel chart-panel evolution"><div className="panel-heading"><div><h2>Evolución de los cursos bíblicos</h2><p>Valores reportados en cada mes del año de servicio</p></div><Badge tone="orange">{filters.year}</Badge></div><div className="chart short"><ResponsiveContainer width="100%" height="100%"><AreaChart data={d.trend.map((r:Row)=>({...r,courses:r.reports?r.courses:null}))}><defs><linearGradient id="courseFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#ef762e" stopOpacity={.2}/><stop offset="100%" stopColor="#ef762e" stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="3 4" vertical={false} stroke="#eeeae5"/><XAxis dataKey="label" axisLine={false} tickLine={false} tick={{fontSize:11}}/><YAxis axisLine={false} tickLine={false} tick={{fontSize:11}}/><Tooltip/><Area type="monotone" dataKey="courses" name="Cursos reportados" stroke="#ef762e" strokeWidth={2.5} fill="url(#courseFill)" dot={{r:4,fill:'#ef762e',stroke:'#fff',strokeWidth:2}} connectNulls={false}/></AreaChart></ResponsiveContainer></div></div>
 <div className="panel"><div className="panel-heading"><div><h2>Avance de quienes contabilizan horas</h2><p>Referencia al corte · las metas de regulares se evalúan por año de servicio</p></div><Target size={20}/></div>{d.goals.length?<Table headers={['Publicador','Predicación','Horas','Referencia al corte','Avance','Comentarios']}>{d.goals.map((g:Row)=><tr key={g.publisher.id}><td><Person p={g.publisher} onClick={()=>setDialog({kind:'person',person:g.publisher})}/></td><td><Badge>{g.type?.name||'Por revisar'}</Badge></td><td className="number strong">{nf(g.hours)} h</td><td>{g.target==null?<Badge tone="amber">Meta histórica por confirmar</Badge>:<><b>{nf(g.target)} h</b>{g.missing>0&&<small className="cell-note">{g.missing} mes(es) pendiente(s)</small>}</>}</td><td><div className="progress-cell"><div className="progress"><i style={{width:`${Math.min(100,g.target?g.hours/g.target*100:0)}%`}}/></div><span>{g.target?nf(g.hours/g.target*100)+'%':'—'}</span></div></td><td><button className="comment-button" disabled={!g.comments.length} onClick={()=>setDialog({kind:'comments',person:g.publisher,reports:g.comments})}><MessageSquare size={16}/>{g.comments.length||'—'}</button></td></tr>)}</Table>:<Empty title="No hay metas aplicables" text="Selecciona un período o grupo con personas que contabilicen horas."/>}</div>
 {d.historyUnverified&&<div className="notice"><Info size={16}/><span>Los estados y grupos anteriores a la migración no tienen fechas históricas confirmadas. Las agrupaciones usan el maestro disponible y están señaladas para revisión.</span></div>}
 </>;
}

function Publishers(){const{data,filters,setDialog}=useApp();const[q,setQ]=useState(''),[status,setStatus]=useState(''),[offset,setOffset]=useState(0);const list=data.publishers.filter((p:Row)=>(!filters.group||p.group_id===filters.group)&&(!status||p.status===status)&&`${p.alias} ${p.full_name} ${p.code}`.toLowerCase().includes(q.toLowerCase())).sort((a:Row,b:Row)=>a.alias.localeCompare(b.alias));return <><div className="panel"><div className="list-toolbar"><div className="search"><Search size={16}/><input placeholder="Buscar por apodo, nombre o código…" value={q} onChange={e=>{setQ(e.target.value);setOffset(0);}}/></div><select value={status} onChange={e=>{setStatus(e.target.value);setOffset(0);}}><option value="">Todos los estados</option>{data.catalogs.filter((c:Row)=>c.category==='status').map((c:Row)=><option key={c.id} value={c.id}>{c.name}</option>)}</select><span className="muted">{list.length} personas</span></div><Table headers={['Publicador','Grupo','Clasificación','Predicación actual','Estado','']}>
 {list.slice(offset,offset+20).map((p:Row)=><tr key={p.id}><td><Person p={p} onClick={()=>setDialog({kind:'person',person:p})}/></td><td>{data.groups.find((g:Row)=>g.id===p.group_id)?.name||'Sin grupo'}</td><td>{data.catalogs.find((c:Row)=>c.id===p.role)?.name||p.role}<small className="cell-note">{p.baptized?'Bautizado(a)':'No bautizado(a)'}</small></td><td><Badge tone={p.preaching_type_id==='PUB'?'neutral':'orange'}>{data.types.find((t:Row)=>t.id===p.preaching_type_id)?.name}</Badge></td><td><Badge tone={p.status==='ACTIVO'?'green':p.status==='INACTIVO'?'amber':'neutral'}>{data.catalogs.find((c:Row)=>c.id===p.status)?.name||p.status}</Badge></td><td><button className="icon-button" aria-label={`Ver ${p.alias}`} onClick={()=>setDialog({kind:'person',person:p})}><ChevronRight size={18}/></button></td></tr>)}
 </Table>{!list.length&&<Empty/>}<Pagination count={list.length} offset={offset} setOffset={setOffset}/></div></>;}
function Pagination({count,offset,setOffset}:any){return <div className="pagination"><span>{count?offset+1:0}–{Math.min(offset+20,count)} de {count}</span><div><button className="icon-button" disabled={!offset} onClick={()=>setOffset(Math.max(0,offset-20))} aria-label="Anterior"><ChevronLeft size={17}/></button><button className="icon-button" disabled={offset+20>=count} onClick={()=>setOffset(offset+20)} aria-label="Siguiente"><ChevronRight size={17}/></button></div></div>;}
function Groups(){const{data,setDialog,go,setFilters}=useApp();return <div className="groups-grid">{data.groups.map((g:Row)=>{const ps=data.publishers.filter((p:Row)=>p.group_id===g.id),leader=data.users.find((u:Row)=>u.id===g.leader_id),assistant=data.users.find((u:Row)=>u.id===g.assistant_id);return <div className="panel group-card" key={g.id}><div className="group-title"><span className="group-icon"><UsersRound size={23}/></span><div><h2>{g.name}</h2><small>{g.code} · <span className="green-text">{g.active?'Habilitado':'Inactivo'}</span></small></div>{can(data.actor,'groups.write')&&<button className="icon-button" onClick={()=>setDialog({kind:'form',entity:'group',data:g})} aria-label={`Editar ${g.name}`}><Pencil size={16}/></button>}</div><div className="group-numbers"><div><b>{ps.length}</b><span>integrantes</span></div><div><b>{ps.filter((p:Row)=>p.status==='ACTIVO').length}</b><span>activos</span></div><div><b>{ps.filter((p:Row)=>p.status==='INACTIVO').length}</b><span>inactivos</span></div></div><div className="responsible"><UserRound size={16}/><div><small>ENCARGADO</small><strong>{leader?.name||'Usuario por vincular'}</strong></div></div><div className="responsible"><UserRound size={16}/><div><small>AUXILIAR</small><strong>{assistant?.name||'Usuario por vincular'}</strong></div></div>{g.notes&&<p className="group-note">{g.notes}</p>}<button className="group-link" onClick={()=>{setFilters((f:Row)=>({...f,group:g.id,person:''}));go('publishers');}}>Ver integrantes <ArrowRight size={16}/></button></div>;})}</div>;}
function Types(){const{data,setDialog}=useApp();return <><div className="notice"><Info size={17}/><span>Metas iniciales definidas por el administrador. Cada cambio guarda una versión con vigencia mensual.</span></div><div className="section-actions">{can(data.actor,'catalogs.write')&&<Button primary onClick={()=>setDialog({kind:'form',entity:'type'})}><Plus size={16}/> Nuevo tipo</Button>}</div><div className="types-grid">{data.types.map((t:Row)=><div className="panel type-card" key={t.id}><div className="panel-heading"><span className="metric-icon orange"><BookOpen size={20}/></span><Badge tone={t.active?'green':'neutral'}>{t.active?'Vigente':'Inactivo'}</Badge></div><h2>{t.name}</h2><div className="type-goal">{t.goal_kind==='annual'?t.annual_goal:t.counts_hours?t.monthly_goal:'—'}<span>{t.goal_kind==='annual'?'h / año de servicio':t.counts_hours?'h / mes':'Sin cómputo de horas'}</span></div><p>{t.description}</p>{t.goal_kind==='annual'&&<small>Referencia: {t.monthly_reference} h/mes · proporcional por vigencia</small>}{t.requires_campaign===1&&<Badge tone="amber">Requiere campaña habilitada</Badge>}<div className="type-foot"><span>{t.id} · {parseJSON(t.versions,[]).length} versión(es)</span>{can(data.actor,'catalogs.write')&&<button className="text-button" onClick={()=>setDialog({kind:'form',entity:'type',data:t})}>Configurar <Pencil size={13}/></button>}</div></div>)}</div></>;}

function Reports(){const{data,filters,setFilters,setDialog,request,refresh,notify,setDirty}=useApp();const[edits,setEdits]=useState<Row>({}),[saving,setSaving]=useState(false),[q,setQ]=useState('');const month=filters.month||serviceMonths(Number(filters.year)).filter(m=>m<=currentMonth()).at(-1)||currentMonth();const group=filters.group||data.groups[0]?.id||'';const period=data.periods.find((p:Row)=>p.month===month);const people=data.publishers.filter((p:Row)=>valueAt(p,'group',month,data.histories)===group&&['ACTIVO','INACTIVO'].includes(valueAt(p,'status',month,data.histories))&&p.alias.toLowerCase().includes(q.toLowerCase())).sort((a:Row,b:Row)=>a.alias.localeCompare(b.alias));
 useEffect(()=>{setDirty(Object.keys(edits).length>0);return()=>setDirty(false);},[edits,setDirty]);
 const record=(p:Row)=>data.reports.find((r:Row)=>r.publisher_id===p.id&&r.month===month);const value=(p:Row)=>{const r=record(p);return{participation:r?.participation??null,hours:r?.hours??null,courses:r?.courses??null,comment:r?.comment||'',...edits[p.id]};};
 const update=(p:Row,key:string,v:any)=>setEdits((s:Row)=>({...s,[p.id]:{...value(p),[key]:v}}));
 const save=async(ps:Row[],submit:boolean)=>{setSaving(true);let done=0;try{for(const p of ps){const r=record(p),v=value(p);if(r&&r.state!=='draft')continue;if(submit&&v.participation==null)continue;if(!submit&&!edits[p.id])continue;await request({action:'report',data:{publisher_id:p.id,month,version:r?.version,submit,...v}});setEdits((e:Row)=>{const n={...e};delete n[p.id];return n;});done++;}await refresh();notify(`${done} informe(s) ${submit?'enviado(s)':'guardado(s)'}.`);}catch(e:any){await refresh();notify(e.message,'error');}finally{setSaving(false);}};
 const received=data.reports.filter((r:Row)=>r.month===month&&r.group_id===group&&r.state!=='draft').length;
 return <><div className="panel capture-toolbar"><Field label="Año de servicio"><input type="number" min="2020" max="2100" value={filters.year} onChange={e=>{if(Object.keys(edits).length&&!window.confirm('Hay cambios sin guardar. ¿Cambiar de año y descartarlos?'))return;setEdits({});setFilters((f:Row)=>({...f,year:Number(e.target.value),month:''}));}}/></Field><Field label="Mes"><select value={month} onChange={e=>{if(Object.keys(edits).length&&!window.confirm('Hay cambios sin guardar. ¿Cambiar de mes y descartarlos?'))return;setEdits({});setFilters((f:Row)=>({...f,month:e.target.value}));}}>{serviceMonths(Number(filters.year)).map((m,i)=><option disabled={m>currentMonth()} value={m} key={m}>{MONTHS[i]} {m.slice(0,4)}</option>)}</select></Field><Field label="Grupo"><select value={group} onChange={e=>{if(Object.keys(edits).length&&!window.confirm('Hay cambios sin guardar. ¿Cambiar de grupo y descartarlos?'))return;setEdits({});setFilters((f:Row)=>({...f,group:e.target.value,person:''}));}}>{data.groups.map((g:Row)=><option value={g.id} key={g.id}>{g.name}</option>)}</select></Field><div className="period-action"><Badge tone={period?.state==='closed'?'amber':'green'}>{period?.state==='closed'?<LockKeyhole size={12}/>:<UnlockKeyhole size={12}/>} Período {period?.state==='closed'?'cerrado':'abierto'}</Badge>{can(data.actor,'periods.write')&&<button className="text-button" onClick={()=>setDialog({kind:'period',month,period})}>{period?.state==='closed'?'Reabrir':'Cerrar período'}</button>}</div></div>
 <div className="capture-summary"><div><ClipboardList size={20}/><span><b>{data.groups.find((g:Row)=>g.id===group)?.name}</b><small>{monthName(month)} · {received} informes recibidos</small></span></div><div><Button disabled={saving||period?.state==='closed'||!Object.keys(edits).length} onClick={()=>save(people,false)}><Check size={16}/> Guardar borradores</Button><Button primary disabled={saving||period?.state==='closed'||!can(data.actor,'reports.submit')} onClick={()=>save(people,true)}>{saving?<LoaderCircle className="spin" size={16}/>:<Send size={16}/>} Enviar completos</Button></div></div>
 <div className="panel"><div className="list-toolbar"><div className="search"><Search size={16}/><input placeholder="Buscar publicador del grupo…" value={q} onChange={e=>setQ(e.target.value)}/></div><small className="muted">Los informes enviados quedan bloqueados para los encargados.</small></div><Table headers={['Publicador','Participación','Horas','Cursos bíblicos','Comentario','Estado','']}>
 {people.map((p:Row)=>{const r=record(p),v=value(p),type=data.types.find((t:Row)=>t.id===(r?.type_id||valueAt(p,'preaching',month,data.histories))),counts=r?!!r.counts_hours:!!type?.counts_hours,locked=r&&r.state!=='draft',disabled=locked||period?.state==='closed';return <tr className="capture-row" key={p.id}><td><strong>{p.alias}</strong><small className="cell-note">{data.catalogs.find((c:Row)=>c.id===valueAt(p,'role',month,data.histories))?.name||'Hermano(a)'} · {p.baptized?'Bautizado(a)':'No bautizado(a)'}</small><Badge tone={counts?'orange':'neutral'}>{type?.name||'Por revisar'}</Badge></td><td><div className="segmented">{['SI','NO'].map(x=><button key={x} disabled={disabled} className={v.participation===x?'active':''} onClick={()=>update(p,'participation',x)}>{x==='SI'?'Sí':'No'}</button>)}</div></td><td><input aria-label={`Horas de ${p.alias}`} className="number-input" type="number" min="0" step="0.25" disabled={disabled||!counts} placeholder={counts?'—':'No aplica'} value={counts?v.hours??'':''} onChange={e=>update(p,'hours',e.target.value===''?null:Number(e.target.value))}/></td><td><input aria-label={`Cursos de ${p.alias}`} className="number-input" type="number" min="0" step="1" disabled={disabled} placeholder="—" value={v.courses??''} onChange={e=>update(p,'courses',e.target.value===''?null:Number(e.target.value))}/></td><td><textarea aria-label={`Comentario de ${p.alias}`} disabled={disabled} placeholder="Añadir observación…" value={v.comment} rows={1} onChange={e=>update(p,'comment',e.target.value)}/></td><td><Badge tone={locked?'green':edits[p.id]?'orange':'neutral'}>{locked?'Enviado':edits[p.id]?'Sin guardar':r?'Borrador':'Pendiente'}</Badge></td><td>{locked?<div className="row-actions">{can(data.actor,'reports.correct')&&<button className="icon-button" aria-label={`Corregir informe de ${p.alias}`} onClick={()=>setDialog({kind:'report',person:p,report:r})}><Pencil size={15}/></button>}<button className="icon-button" aria-label={`Solicitar corrección de ${p.alias}`} onClick={()=>setDialog({kind:'correction',person:p,report:r})}><MessageSquare size={15}/></button></div>:<button className="icon-button" disabled={saving||disabled||!edits[p.id]} title="Guardar borrador" onClick={()=>save([p],false)}><Check size={17}/></button>}</td></tr>;})}</Table>{!people.length&&<Empty title="No hay publicadores para esta selección" text="Revisa el grupo, el mes y las vigencias."/>}</div><div className="notice"><Info size={16}/><span>Una respuesta sin registrar no equivale a NO. Los datos vacíos se conservan y las horas se habilitan según la predicación vigente en ese mes.</span></div></>;
}

function Assignments(){const{data,setDialog}=useApp();const[tab,setTab]=useState('histories'),[q,setQ]=useState(''),[offset,setOffset]=useState(0);const hs=data.histories.filter((h:Row)=>{const p=data.publishers.find((p:Row)=>p.id===h.publisher_id);return p?.alias.toLowerCase().includes(q.toLowerCase());}).sort((a:Row,b:Row)=>b.start_month.localeCompare(a.start_month));return <><div className="tabs"><button className={tab==='histories'?'active':''} onClick={()=>setTab('histories')}>Vigencias mensuales</button><button className={tab==='campaigns'?'active':''} onClick={()=>setTab('campaigns')}>Campañas</button></div><div className="section-actions"><Button primary onClick={()=>setDialog({kind:tab==='campaigns'?'form':'assignment',entity:tab==='campaigns'?'campaign':undefined})}><Plus size={16}/>{tab==='campaigns'?'Nueva campaña':'Nueva vigencia'}</Button></div>{tab==='campaigns'?<div className="panel"><Table headers={['Campaña','Inicio','Último mes vigente','Tipo','Estado','']}>{data.campaigns.map((c:Row)=><tr key={c.id}><td><strong>{c.name}</strong><small className="cell-note">{c.notes}</small></td><td>{monthName(c.start_month)}</td><td>{monthName(c.end_month)}</td><td>{data.types.find((t:Row)=>t.id===c.type_id)?.name}</td><td><Badge tone={c.active?'green':'neutral'}>{c.active?'Habilitada':'Inactiva'}</Badge></td><td><button className="icon-button" onClick={()=>setDialog({kind:'form',entity:'campaign',data:c})}><Pencil size={15}/></button></td></tr>)}</Table>{!data.campaigns.length&&<Empty title="Crea la primera campaña" text="Configura sus meses para habilitar las asignaciones de auxiliar por campaña."/>}</div>:<div className="panel"><div className="list-toolbar"><div className="search"><Search size={16}/><input placeholder="Buscar por apodo…" value={q} onChange={e=>{setQ(e.target.value);setOffset(0);}}/></div><span className="muted">{hs.length} tramos de vigencia</span></div><Table headers={['Publicador','Concepto','Valor','Inicio','Último mes','Origen','']}>{hs.slice(offset,offset+20).map((h:Row)=>{const p=data.publishers.find((p:Row)=>p.id===h.publisher_id),name=h.kind==='preaching'?data.types.find((t:Row)=>t.id===h.value)?.name:h.kind==='group'?data.groups.find((g:Row)=>g.id===h.value)?.name:data.catalogs.find((c:Row)=>c.id===h.value)?.name;return <tr key={h.id}><td>{p?.alias}</td><td>{{preaching:'Predicación',status:'Estado',role:'Clasificación',group:'Grupo'}[h.kind as string]}</td><td>{name||h.value}</td><td>{monthName(h.start_month)}</td><td>{h.end_month?monthName(h.end_month):'Continúa'}</td><td><Badge tone={h.unverified?'amber':'neutral'}>{h.unverified?'Por confirmar':h.origin==='excel'?'Excel':'Web'}</Badge></td><td>{!h.end_month&&<button className="text-button" onClick={()=>setDialog({kind:'closeHistory',history:h})}>Cerrar</button>}</td></tr>;})}</Table><Pagination count={hs.length} offset={offset} setOffset={setOffset}/></div>}<div className="notice"><Info size={16}/><span>Inicio y último mes vigente son inclusivos. Los cambios conservan los informes anteriores y evitan superposiciones.</span></div></>;}
function Catalogs(){const{data,setDialog}=useApp();return <>{['role','status','condition'].map(category=><div className="panel" key={category}><div className="panel-heading"><div><h2>{{role:'Clasificación congregacional',status:'Estados del publicador',condition:'Condición'}[category]}</h2><p>Independiente del bautismo y el tipo de predicación</p></div><Button small onClick={()=>setDialog({kind:'form',entity:'catalog',data:{category}})}><Plus size={15}/> Agregar</Button></div><Table headers={['Código','Nombre','Estado','']}>{data.catalogs.filter((c:Row)=>c.category===category).map((c:Row)=><tr key={c.id}><td>{c.id}</td><td>{c.name}</td><td><Badge tone={c.active?'green':'neutral'}>{c.active?'Habilitado':'Inactivo'}</Badge></td><td><button className="icon-button" onClick={()=>setDialog({kind:'form',entity:'catalog',data:c})}><Pencil size={15}/></button></td></tr>)}</Table></div>)}</>;}

function Exports(){const{data,filters,setDialog,request,notify}=useApp();const[selected,setSelected]=useState<string[]>([]),[q,setQ]=useState(''),[mode,setMode]=useState('organized'),[year1,setYear1]=useState(Number(filters.year)-1),[year2,setYear2]=useState(Number(filters.year)),[cutoff,setCutoff]=useState(today()),[status,setStatus]=useState('operational'),[progress,setProgress]=useState<Row|null>(null);const list=data.publishers.filter((p:Row)=>(!filters.group||p.group_id===filters.group)&&(!filters.person||p.id===filters.person)&&p.alias.toLowerCase().includes(q.toLowerCase())&&(status==='all'||status==='operational'?status==='all'||['ACTIVO','INACTIVO'].includes(p.status):p.status===status));const ids=selected.filter(id=>list.some((p:Row)=>p.id===id));const run=async()=>{if(!ids.length)return;try{setProgress({n:0,total:ids.length});const out=await request({action:'export',ids,years:[year1,year2],cutoff}),file=await exportPdfs(out.data,ids,[year1,year2],cutoff,mode,(n,total)=>setProgress({n,total}));saveDownload(file.blob,file.filename);notify(`${ids.length} registro(s) preparado(s).`);}catch(e:any){notify(e.message,'error');}finally{setProgress(null);}};const distribution:Row={};for(const id of ids){const p=data.publishers.find((p:Row)=>p.id===id),folder=folderFor(p,data,cutoff,mode)||'Sin subcarpetas';distribution[folder]=(distribution[folder]||0)+1;}
 return <><div className="export-layout"><div><div className="panel"><div className="panel-heading"><div><h2>Selecciona los publicadores</h2><p>Un PDF por apodo, con dos años de servicio</p></div><Badge tone="orange">{ids.length} seleccionados</Badge></div><div className="list-toolbar"><div className="search"><Search size={16}/><input placeholder="Buscar publicador…" value={q} onChange={e=>setQ(e.target.value)}/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option value="operational">Activos e inactivos</option><option value="all">Todos, incluido archivo</option>{data.catalogs.filter((c:Row)=>c.category==='status').map((c:Row)=><option key={c.id} value={c.id}>{c.name}</option>)}</select></div><div className="export-list"><Table headers={[<input key="all" aria-label="Seleccionar todos" type="checkbox" checked={list.length>0&&list.every((p:Row)=>selected.includes(p.id))} onChange={e=>setSelected(e.target.checked?list.map((p:Row)=>p.id):[])}/>, 'Publicador','Grupo','Vista previa']}>{list.map((p:Row)=><tr key={p.id}><td><input type="checkbox" aria-label={`Seleccionar ${p.alias}`} checked={selected.includes(p.id)} onChange={e=>setSelected(s=>e.target.checked?[...s,p.id]:s.filter(x=>x!==p.id))}/></td><td><strong>{p.alias}</strong><small className="cell-note">{p.full_name}</small></td><td>{data.groups.find((g:Row)=>g.id===p.group_id)?.name||'Archivo'}</td><td><button className="icon-button" title="Vista previa" onClick={()=>setDialog({kind:'preview',person:p,years:[year1,year2],cutoff})}><Eye size={17}/></button></td></tr>)}</Table></div></div></div><aside className="panel export-settings"><div className="panel-heading"><h2>Preparar registros</h2><FileDown size={20}/></div><div className="settings-body"><div className="two-col"><Field label="Primer año"><input type="number" min="2020" max="2100" value={year1} onChange={e=>setYear1(Number(e.target.value))}/></Field><Field label="Segundo año"><input type="number" min="2020" max="2100" value={year2} onChange={e=>setYear2(Number(e.target.value))}/></Field></div><Field label="Fecha de corte"><input type="date" value={cutoff} max={today()} onChange={e=>setCutoff(e.target.value)}/></Field><Field label="Organización de la descarga"><select value={mode} onChange={e=>setMode(e.target.value)}><option value="organized">Carpetas S-21 habituales</option><option value="group">Por grupo</option><option value="type">Por tipo de predicación</option><option value="status">Por estado</option><option value="flat">Sin subcarpetas</option></select></Field><div className="export-distribution"><h4>Distribución de la selección</h4>{Object.entries(distribution).map(([name,n])=><div key={name}><FolderOpen size={14}/><span>{name}</span><b>{String(n)}</b></div>)}{!ids.length&&<p>Selecciona al menos un publicador.</p>}</div><Button primary disabled={!ids.length||!!progress||ids.length>1&&!can(data.actor,'pdf.bulk')} onClick={run}>{progress?<LoaderCircle className="spin" size={17}/>:<Download size={17}/>} {progress?`Preparando ${progress.n} de ${progress.total}`:ids.length===1?'Descargar PDF':'Generar y descargar ZIP'}</Button><p className="muted small-text">A4 · Dos registros por hoja · Notas extensas en anexo · LEEME en descargas masivas</p></div></aside></div></>;
}

function Review(){const{data,setDialog}=useApp();const[tab,setTab]=useState('issues'),[state,setState]=useState('pending'),[offset,setOffset]=useState(0),list=(tab==='issues'?data.issues:data.corrections).filter((r:Row)=>state==='all'||r.state===state);return <><div className="tabs"><button className={tab==='issues'?'active':''} onClick={()=>{setTab('issues');setOffset(0);}}>Revisión de datos <Badge>{data.issues.filter((i:Row)=>i.state==='pending').length}</Badge></button><button className={tab==='corrections'?'active':''} onClick={()=>{setTab('corrections');setOffset(0);}}>Solicitudes de corrección <Badge>{data.corrections.filter((i:Row)=>i.state==='pending').length}</Badge></button></div><div className="panel"><div className="list-toolbar"><select value={state} onChange={e=>{setState(e.target.value);setOffset(0);}}><option value="pending">Pendientes</option><option value="resolved">Resueltas</option><option value="all">Todas</option></select><span className="muted">{list.length} registros</span></div><Table headers={['Publicador','Período','Observación','Estado','']}>{list.slice(offset,offset+20).map((r:Row)=>{const p=data.publishers.find((p:Row)=>p.id===r.publisher_id);return <tr key={r.id}><td>{p?.alias||'Datos generales'}</td><td>{r.month?monthName(r.month):'Maestro'}</td><td><strong>{r.message}</strong><small className="cell-note">{r.kind||r.field}</small></td><td><Badge tone={r.state==='pending'?'amber':'green'}>{r.state==='pending'?'Pendiente':'Resuelta'}</Badge></td><td><Button small onClick={()=>setDialog({kind:'issue',issue:r,entity:tab==='issues'?'issue':'correction',person:p})}>Revisar <ArrowUpRight size={13}/></Button></td></tr>;})}</Table>{!list.length&&<Empty title="No hay revisiones en esta selección" text="Las nuevas solicitudes aparecerán aquí."/>}<Pagination count={list.length} offset={offset} setOffset={setOffset}/></div></>;}
function UsersPage(){const{data,setDialog}=useApp();const[tab,setTab]=useState('users');return <><div className="notice"><ShieldCheck size={18}/><span>Autoriza las cuentas y sus grupos. Cada persona ingresa con su correo y contraseña de Monterrico. Los permisos de S-21 son independientes de S-13. Guardar un usuario no envía invitaciones.</span></div><div className="tabs"><button className={tab==='users'?'active':''} onClick={()=>setTab('users')}>Usuarios</button><button className={tab==='profiles'?'active':''} onClick={()=>setTab('profiles')}>Perfiles y permisos</button></div><div className="section-actions"><Button primary onClick={()=>setDialog({kind:'form',entity:tab==='users'?'user':'profile'})}><Plus size={16}/>{tab==='users'?'Autorizar usuario':'Nuevo perfil'}</Button></div><div className="panel">{tab==='users'?<Table headers={['Usuario','Perfil','Grupos autorizados','Estado','']}>{data.users.map((u:Row)=><tr key={u.id}><td><strong>{u.name}</strong><small className="cell-note">{u.email}</small></td><td>{data.profiles.find((p:Row)=>p.id===u.profile_id)?.name}</td><td>{parseJSON(u.groups_json,[]).map((id:string)=>data.groups.find((g:Row)=>g.id===id)?.name||id).join(', ')||'Según permisos del perfil'}</td><td><Badge tone={u.active?'green':'neutral'}>{u.active?'Habilitado':'Inactivo'}</Badge></td><td><button className="icon-button" onClick={()=>setDialog({kind:'form',entity:'user',data:u})}><Pencil size={16}/></button></td></tr>)}</Table>:<Table headers={['Perfil','Permisos habilitados','']}>{data.profiles.map((p:Row)=><tr key={p.id}><td><strong>{p.name}</strong></td><td>{parseJSON(p.permissions,[]).length} permisos</td><td><Button small onClick={()=>setDialog({kind:'form',entity:'profile',data:p})}>Configurar</Button></td></tr>)}</Table>}</div></>;}

function Imports(){const{data,notify,request,refresh}=useApp();const[payload,setPayload]=useState<Row|null>(null),[filename,setFilename]=useState(''),[loading,setLoading]=useState(false),[progress,setProgress]=useState(''),ref=useRef<HTMLInputElement>(null);const choose=async(file:File)=>{setLoading(true);try{const p=file.name.toLowerCase().endsWith('.json')?await (async()=>{const x=JSON.parse(await file.text()),s=x.backup||x;if(!Array.isArray(s.publishers)||!Array.isArray(s.reports))throw new Error('El respaldo no tiene la estructura esperada.');return{publishers:s.publishers,reports:s.reports,histories:s.histories||[],issues:s.issues||[],groups:s.groups||[],summary:{people:s.publishers.length,reports:s.reports.length,issues:(s.issues||[]).length,restore:true}};})():await readExcel(file,data);setPayload(p);setFilename(file.name);}catch(e:any){notify(e.message,'error');}finally{setLoading(false);}};
 const run=async()=>{if(!payload)return;setLoading(true);try{const start=await request({action:'start',filename,summary:payload.summary},'/api/import');for(const entity of ['groups','publishers','histories','reports','issues']){const list=payload[entity]||[];for(let i=0;i<list.length;i+=25){setProgress(`${{groups:'Grupos',publishers:'Publicadores',histories:'Vigencias',reports:'Informes',issues:'Revisiones'}[entity]} · ${Math.min(i+25,list.length)} de ${list.length}`);await request({action:'chunk',job:start.id,entity,rows:list.slice(i,i+25)},'/api/import');}}await request({action:'finish',job:start.id},'/api/import');setPayload(null);await refresh();notify('Importación completada.');}catch(e:any){notify(e.message,'error');await refresh();}finally{setLoading(false);setProgress('');}};
 const backup=async()=>{try{const result=await request({action:'backup'});saveDownload(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}),`S21_respaldo_${today()}.json`);notify('Respaldo descargado.');}catch(e:any){notify(e.message,'error');}};
 return <><div className="import-grid"><div className="panel upload-card"><div className="metric-icon orange"><Upload size={23}/></div><h2>Importar información</h2><p>Excel con las hojas DATA, GRUPOS y HORAS, o un respaldo JSON del sistema.</p><input type="file" ref={ref} accept=".xlsx,.xls,.json" className="visually-hidden" aria-label="Seleccionar archivo de importación" onChange={e=>{const f=e.target.files?.[0];if(f)choose(f);e.target.value='';}}/><Button primary disabled={loading} onClick={()=>ref.current?.click()}>{loading?<LoaderCircle className="spin" size={17}/>:<Plus size={17}/>} Seleccionar archivo</Button><small>Se revisa la información antes de incorporarla.</small></div><div className="panel upload-card"><div className="metric-icon green"><Database size={23}/></div><h2>Respaldo de información</h2><p>Descarga los datos de tu ámbito autorizado. La recuperación combina registros por identificador; conserva los usuarios y permisos actuales.</p><Button disabled={!can(data.actor,'backup')} onClick={backup}><Download size={16}/> Descargar respaldo JSON</Button><small>La información personal queda dentro de tu archivo.</small></div></div>
 {payload&&<div className="panel"><div className="panel-heading"><div><h2>Vista previa de importación</h2><p>{filename}</p></div><Badge tone="orange">Pendiente de confirmar</Badge></div><div className="import-summary">{[['Personas',payload.summary.people],['Informes',payload.summary.reports],['Duplicados idénticos',payload.summary.exactDuplicates||0],['Conflictos',payload.summary.conflicts||0],['Observaciones',payload.summary.issues||0]].map(([label,n])=><div key={String(label)}><strong>{nf(n)}</strong><span>{label}</span></div>)}</div><div className="notice"><AlertCircle size={17}/><span>Esta operación incorpora y actualiza datos por código y mes. Las versiones distintas de un mismo informe quedan pendientes de revisión. Los registros ajenos a GRUPOS no se incorporan al padrón.</span></div><div className="dialog-actions"><Button disabled={loading} onClick={()=>setPayload(null)}>Cancelar</Button><Button primary disabled={loading} onClick={run}>{loading?<LoaderCircle size={16} className="spin"/>:<Check size={16}/>} {progress||'Confirmar importación y actualización'}</Button></div></div>}
 <div className="panel"><div className="panel-heading"><h2>Importaciones realizadas</h2></div><Table headers={['Archivo','Fecha','Personas','Informes','Estado']}>{data.imports.map((i:Row)=>{const s=parseJSON<Row>(i.summary,{});return <tr key={i.id}><td>{i.filename}</td><td>{labelDate(i.created_at)}</td><td>{s.people}</td><td>{s.reports}</td><td><Badge tone={s.state==='completed'?'green':'amber'}>{s.state==='completed'?'Completada':'En curso o incompleta'}</Badge></td></tr>;})}</Table>{!data.imports.length&&<Empty title="Aún no hay importaciones" text="Carga tu Excel para incorporar los primeros datos."/>}</div></>;}
function Audit(){const{data,setDialog}=useApp();const[q,setQ]=useState(''),[offset,setOffset]=useState(0);const list=data.audit.filter((a:Row)=>`${a.actor} ${a.action} ${a.entity} ${a.reason}`.toLowerCase().includes(q.toLowerCase()));return <div className="panel"><div className="list-toolbar"><div className="search"><Search size={16}/><input placeholder="Buscar usuario, operación o motivo…" value={q} onChange={e=>{setQ(e.target.value);setOffset(0);}}/></div><span className="muted">Últimas 500 operaciones</span></div><Table headers={['Fecha y hora','Usuario','Operación','Registro','Motivo','']}>{list.slice(offset,offset+20).map((a:Row)=><tr key={a.id}><td>{new Date(a.at).toLocaleString('es-PE',{timeZone:'America/Lima'})}</td><td>{a.actor}</td><td><Badge>{a.action}</Badge></td><td>{a.entity}</td><td>{a.reason||'—'}</td><td><button className="icon-button" title="Ver cambios" onClick={()=>setDialog({kind:'audit',entry:a})}><Eye size={16}/></button></td></tr>)}</Table><Pagination count={list.length} offset={offset} setOffset={setOffset}/></div>;}

function Dialog(){const{dialog:d,setDialog}=useApp(),ref=useRef<HTMLDivElement>(null);useEffect(()=>{const previous=document.activeElement as HTMLElement;ref.current?.querySelector<HTMLElement>('button,input,select,textarea')?.focus();const listener=(e:KeyboardEvent)=>{if(e.key==='Escape')setDialog(null);if(e.key==='Tab'){const els=ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href],iframe');if(!els?.length)return;const a=els[0],b=els[els.length-1];if(e.shiftKey&&document.activeElement===a){e.preventDefault();b.focus();}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a.focus();}}};document.addEventListener('keydown',listener);return()=>{document.removeEventListener('keydown',listener);previous?.focus();};},[d.kind,setDialog]);
 const titles:Row={form:{publisher:d.data?.id?'Editar publicador':'Nuevo publicador',group:d.data?.id?'Editar grupo':'Nuevo grupo',type:'Configurar tipo de predicación',catalog:'Configurar catálogo',campaign:'Configurar campaña',user:'Autorizar usuario',profile:'Perfil y permisos'}[d.entity as string],person:'Ficha del publicador',comments:'Observaciones del período',report:'Corregir informe',correction:'Solicitar corrección',assignment:'Nueva vigencia mensual',closeHistory:'Cerrar vigencia',period:d.period?.state==='closed'?'Reabrir período':'Cerrar período',issue:'Revisión del registro',audit:'Detalle del cambio',preview:'Vista previa S-21'};
 return <div className="dialog-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)setDialog(null);}}><div ref={ref} className={`dialog ${['person','comments'].includes(d.kind)?'drawer':''} ${d.kind==='preview'?'pdf-dialog':''}`} role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div className="dialog-heading"><div><span className="eyebrow">S-21 MONTERRICO</span><h2 id="dialog-title">{titles[d.kind]}</h2></div><button className="icon-button" onClick={()=>setDialog(null)} aria-label="Cerrar ventana"><X size={21}/></button></div><div className="dialog-body">{d.kind==='form'?<EntityForm/>:d.kind==='person'?<PersonDetail/>:d.kind==='comments'?<Comments/>:d.kind==='assignment'?<AssignmentForm/>:d.kind==='report'?<ReportForm/>:d.kind==='preview'?<Preview/>:d.kind==='issue'?<IssueDetail/>:d.kind==='audit'?<AuditDetail/>:<ActionForm/>}</div></div></div>;
}

function EntityForm(){const{data,dialog:d,setDialog,mutate,busy}=useApp();const entity=d.entity,old=d.data||{},[v,setV]=useState<Row>(()=>({active:1,gender:'MASCULINO',baptized:1,role:'HERMANO',status:'ACTIVO',condition:'OO',preaching_type_id:'PUB',group_id:data.groups[0]?.id,counts_hours:0,goal_kind:'none',requires_campaign:0,category:old.category||'role',profile_id:'consulta',permissions:'[]',groups_json:'[]',effective_month:currentMonth(),...old}));
 const update=(key:string,value:any)=>setV((s:Row)=>({...s,[key]:value}));const opt=(list:Row[],label='name')=>list.map(r=>({value:r.id,label:r[label]}));let fields:Row[]=[];
 if(entity==='publisher')fields=[{key:'code',label:'Código',required:true},{key:'alias',label:'Apodo',required:true},{key:'names',label:'Nombres',required:true},{key:'surnames',label:'Apellidos',required:true},{key:'full_name',label:'Nombre completo para S-21',required:true,wide:true},{key:'gender',label:'Género',options:[{value:'MASCULINO',label:'Masculino'},{value:'FEMENINO',label:'Femenino'}]},{key:'birth_date',label:'Fecha de nacimiento',type:'date'},{key:'baptized',label:'Bautizado(a)',type:'checkbox'},{key:'baptism_date',label:'Fecha de bautismo',type:'date',disabled:!v.baptized},{key:'condition',label:'Condición',options:opt(data.catalogs.filter((c:Row)=>c.category==='condition'))},{key:'role',label:'Clasificación congregacional',options:opt(data.catalogs.filter((c:Row)=>c.category==='role'))},{key:'status',label:'Estado',options:opt(data.catalogs.filter((c:Row)=>c.category==='status'))},{key:'group_id',label:'Grupo',options:opt(data.groups)},{key:'preaching_type_id',label:'Predicación actual',options:opt(data.types.filter((t:Row)=>!t.requires_campaign||old.preaching_type_id===t.id)),hint:'El auxiliar por campaña se asigna desde Vigencias, con sus meses y campaña.'},{key:'effective_month',label:'Mes de vigencia del cambio',type:'month',hint:'Se conservan las clasificaciones de los meses anteriores.'},{key:'notes',label:'Observaciones',type:'textarea',wide:true},{key:'reason',label:'Motivo del cambio',wide:true}];
 if(entity==='group')fields=[{key:'code',label:'Código',required:true},{key:'name',label:'Nombre del grupo',required:true},{key:'leader_id',label:'Encargado',options:opt(data.users.filter((u:Row)=>u.active!==0)),empty:'Sin usuario vinculado'},{key:'assistant_id',label:'Auxiliar',options:opt(data.users.filter((u:Row)=>u.active!==0)),empty:'Sin usuario vinculado'},{key:'active',label:'Grupo habilitado',type:'checkbox'},{key:'notes',label:'Observaciones y responsables anteriores',type:'textarea',wide:true}];
 if(entity==='type')fields=[...(!old.id?[{key:'id',label:'Código del tipo',required:true}]:[]),{key:'name',label:'Nombre',required:true},{key:'counts_hours',label:'Contabiliza horas',type:'checkbox'},{key:'requires_campaign',label:'Requiere campaña',type:'checkbox'},{key:'goal_kind',label:'Tipo de meta',options:[{value:'none',label:'Sin meta'},{value:'monthly',label:'Mensual'},{value:'annual',label:'Anual'}]},{key:'monthly_goal',label:'Meta mensual (horas)',type:'number'},{key:'annual_goal',label:'Meta anual (horas)',type:'number'},{key:'monthly_reference',label:'Referencia mensual (horas)',type:'number'},{key:'effective_month',label:'Mes inicial de la versión',type:'month',required:true},{key:'active',label:'Tipo habilitado',type:'checkbox'},{key:'description',label:'Descripción',type:'textarea',wide:true}];
 if(entity==='catalog')fields=[...(!old.id?[{key:'id',label:'Código',required:true}]:[]),{key:'category',label:'Catálogo',options:[{value:'role',label:'Clasificación congregacional'},{value:'status',label:'Estado'},{value:'condition',label:'Condición'}]},{key:'name',label:'Nombre',required:true},{key:'active',label:'Habilitado',type:'checkbox'}];
 if(entity==='campaign')fields=[{key:'name',label:'Nombre de la campaña',required:true,wide:true},{key:'start_month',label:'Mes inicial',type:'month',required:true},{key:'end_month',label:'Último mes vigente',type:'month',required:true},{key:'type_id',label:'Tipo de predicación',options:opt(data.types.filter((t:Row)=>t.requires_campaign)),required:true},{key:'active',label:'Campaña habilitada',type:'checkbox'},{key:'notes',label:'Observaciones',type:'textarea',wide:true}];
 if(entity==='user')fields=[{key:'name',label:'Nombre para mostrar',required:true},{key:'email',label:'Correo de su cuenta',type:'email',required:true},{key:'profile_id',label:'Perfil',options:opt(data.profiles),required:true},{key:'publisher_id',label:'Publicador vinculado',options:opt(data.publishers,'alias'),empty:'Sin vínculo'},{key:'active',label:'Usuario habilitado',type:'checkbox'}];
 if(entity==='profile')fields=[{key:'name',label:'Nombre del perfil',required:true,wide:true}];
 const submit=async(e:React.FormEvent)=>{e.preventDefault();const payload={...v};if(entity==='campaign'&&!payload.type_id)payload.type_id=data.types.find((t:Row)=>t.requires_campaign)?.id;if(entity==='group'&&!old.id)payload.id=payload.code;try{await mutate({action:'save',entity,data:payload});setDialog(null);}catch{}};
 return <form onSubmit={submit}><div className="form-grid">{fields.map(f=><div key={f.key} className={f.wide?'span-two':''}><Field label={f.label} hint={f.hint}>{f.options?<select value={v[f.key]??''} onChange={e=>update(f.key,e.target.value||null)} required={f.required}>{f.empty&&<option value="">{f.empty}</option>}{f.options.map((o:Row)=><option key={o.value} value={o.value}>{o.label}</option>)}</select>:f.type==='checkbox'?<div className="checkbox-field"><input type="checkbox" checked={!!v[f.key]} onChange={e=>update(f.key,e.target.checked?1:0)}/><span>{v[f.key]?'Sí':'No'}</span></div>:f.type==='textarea'?<textarea rows={3} value={v[f.key]??''} onChange={e=>update(f.key,e.target.value)}/>:<input type={f.type||'text'} min={f.type==='number'?0:undefined} required={f.required} disabled={f.disabled} value={v[f.key]??''} onChange={e=>update(f.key,f.type==='number'?(e.target.value===''?null:Number(e.target.value)):e.target.value)}/>}</Field></div>)}</div>
 {entity==='user'&&<div className="permission-section"><h3>Grupos autorizados</h3><p>El permiso “Todos los grupos” del perfil prevalece sobre esta selección.</p><div className="checkbox-grid">{data.groups.map((g:Row)=>{const selected=parseJSON<string[]>(v.groups_json,[]);return <label key={g.id}><input type="checkbox" checked={selected.includes(g.id)} onChange={e=>update('groups_json',JSON.stringify(e.target.checked?[...selected,g.id]:selected.filter(x=>x!==g.id)))}/>{g.name}</label>;})}</div></div>}
 {entity==='profile'&&<div className="permission-section"><h3>Permisos del perfil</h3><div className="checkbox-grid">{PERMISSIONS.map(([key,label])=>{const selected=parseJSON<string[]>(v.permissions,[]);return <label key={key}><input type="checkbox" checked={selected.includes(key)} onChange={e=>update('permissions',JSON.stringify(e.target.checked?[...selected,key]:selected.filter(x=>x!==key)))}/>{label}</label>;})}</div></div>}
 {entity==='type'&&old.id&&<div className="version-list"><h3>Versiones registradas</h3>{parseJSON<Row[]>(old.versions,[]).map((x:Row,i:number)=><p key={i}><b>{monthName(x.since)}</b> · {x.goal_kind==='annual'?`${x.annual_goal} h/año · referencia ${x.monthly_reference} h/mes`:x.counts_hours?`${x.monthly_goal} h/mes`:'No contabiliza horas'}</p>)}</div>}
 <div className="dialog-actions"><Button onClick={()=>setDialog(null)}>Cancelar</Button><Button type="submit" primary disabled={busy}>{busy?<LoaderCircle size={16} className="spin"/>:<Check size={16}/>} Guardar cambios</Button></div></form>;
}

function PersonDetail(){const{data,dialog:d,setDialog}=useApp();const p=data.publishers.find((p:Row)=>p.id===d.person.id)||d.person,[tab,setTab]=useState('data'),reports=data.reports.filter((r:Row)=>r.publisher_id===p.id).sort((a:Row,b:Row)=>b.month.localeCompare(a.month));return <><div className="person-hero"><Avatar name={p.alias} size="large"/><div><h2>{p.alias}</h2><p>{p.full_name}</p><Badge tone={p.status==='ACTIVO'?'green':'amber'}>{data.catalogs.find((c:Row)=>c.id===p.status)?.name||p.status}</Badge> <Badge>{p.code}</Badge></div></div><div className="tabs"><button className={tab==='data'?'active':''} onClick={()=>setTab('data')}>Datos principales</button><button className={tab==='reports'?'active':''} onClick={()=>setTab('reports')}>Informes ({reports.length})</button><button className={tab==='history'?'active':''} onClick={()=>setTab('history')}>Historial</button></div>
 {tab==='data'?<><div className="detail-grid">{[['Grupo',data.groups.find((g:Row)=>g.id===p.group_id)?.name],['Clasificación',data.catalogs.find((c:Row)=>c.id===p.role)?.name],['Predicación',data.types.find((t:Row)=>t.id===p.preaching_type_id)?.name],['Bautizado(a)',p.baptized?'Sí':'No'],['Fecha de nacimiento',labelDate(p.birth_date)],['Fecha de bautismo',p.baptized?labelDate(p.baptism_date):'No aplica'],['Condición',data.catalogs.find((c:Row)=>c.id===p.condition)?.name],['Historia confirmada desde',monthName(p.historical_since)]].map(([key,value])=><div key={String(key)}><small>{key}</small><strong>{value||'Por confirmar'}</strong></div>)}</div>{p.notes&&<div className="note-block">{p.notes}</div>}<div className="dialog-actions">{can(data.actor,'assignments.write')&&<Button onClick={()=>setDialog({kind:'assignment',person:p})}><CalendarDays size={16}/> Nueva vigencia</Button>}{can(data.actor,'publishers.write')&&<Button primary onClick={()=>setDialog({kind:'form',entity:'publisher',data:p})}><Pencil size={16}/> Editar datos</Button>}</div></>:tab==='reports'?<Table headers={['Mes','Participación','Horas','Cursos','Nota','']}>
 {reports.map((r:Row)=><tr key={r.id}><td>{monthName(r.month)}<small className="cell-note">{data.types.find((t:Row)=>t.id===r.type_id)?.name}</small></td><td><Badge tone={r.participation==='SI'?'green':'neutral'}>{r.participation||'Pendiente'}</Badge></td><td>{r.counts_hours?r.hours??'Sin dato':'No aplica'}</td><td>{r.courses??'—'}</td><td><button className="comment-button" disabled={!r.comment} onClick={()=>setDialog({kind:'comments',person:p,reports:[r]})}><MessageSquare size={15}/></button></td><td>{can(data.actor,'reports.correct')&&<button className="icon-button" onClick={()=>setDialog({kind:'report',person:p,report:r})}><Pencil size={14}/></button>}</td></tr>)}</Table>:<div className="timeline">{data.histories.filter((h:Row)=>h.publisher_id===p.id).sort((a:Row,b:Row)=>b.start_month.localeCompare(a.start_month)).map((h:Row)=><div className="timeline-entry" key={h.id}><span className="timeline-dot"/><small>{monthName(h.start_month)} — {h.end_month?monthName(h.end_month):'Continúa'}</small><strong>{{preaching:'Predicación',group:'Grupo',status:'Estado',role:'Clasificación'}[h.kind as string]}: {h.kind==='preaching'?data.types.find((t:Row)=>t.id===h.value)?.name:h.kind==='group'?data.groups.find((g:Row)=>g.id===h.value)?.name:data.catalogs.find((c:Row)=>c.id===h.value)?.name||h.value}</strong><p>{h.notes}</p>{h.unverified===1&&<Badge tone="amber">Por confirmar</Badge>}</div>)}</div>}
 </>;}
function Comments(){const{dialog:d,data}=useApp();return <><div className="person-hero"><Avatar name={d.person.alias}/><div><h2>{d.person.alias}</h2><p>Observaciones de los informes seleccionados</p></div></div><div className="timeline">{d.reports.filter((r:Row)=>r.comment).sort((a:Row,b:Row)=>b.month.localeCompare(a.month)).map((r:Row)=><div className="timeline-entry" key={r.id}><span className="timeline-dot"/><small>{monthName(r.month)} · Año de servicio {serviceYear(r.month)}</small><strong>{data.types.find((t:Row)=>t.id===r.type_id)?.name}</strong><div className="comment-metrics"><Badge>{r.counts_hours?`${r.hours??'Sin dato'} h`:'Sin cómputo de horas'}</Badge><Badge>{r.courses??'Sin dato'} cursos</Badge></div><div className="note-block">{r.comment}</div><small>Registrado: {labelDate(r.updated_at)}</small></div>)}</div></>;}

function AssignmentForm(){const{data,dialog:d,setDialog,mutate,busy}=useApp();const[v,setV]=useState<Row>({publisher_id:d.person?.id||data.publishers[0]?.id,kind:'preaching',value:'PUB',start_month:currentMonth(),end_month:'',campaign_id:'',notes:''});const update=(k:string,x:any)=>setV(s=>({...s,[k]:x}));const choices=v.kind==='preaching'?data.types:v.kind==='group'?data.groups:data.catalogs.filter((c:Row)=>c.category===(v.kind==='role'?'role':'status'));const t=data.types.find((t:Row)=>t.id===v.value);return <form onSubmit={async e=>{e.preventDefault();try{await mutate({action:'assignment',data:v});setDialog(null);}catch{}}}><div className="form-grid"><Field label="Publicador"><select value={v.publisher_id} onChange={e=>update('publisher_id',e.target.value)}>{data.publishers.map((p:Row)=><option key={p.id} value={p.id}>{p.alias}</option>)}</select></Field><Field label="Concepto"><select value={v.kind} onChange={e=>setV(s=>({...s,kind:e.target.value,value:e.target.value==='preaching'?'PUB':e.target.value==='group'?data.groups[0]?.id:e.target.value==='role'?'HERMANO':'ACTIVO'}))}><option value="preaching">Tipo de predicación</option><option value="group">Grupo</option><option value="role">Clasificación congregacional</option><option value="status">Estado</option></select></Field><Field label="Nuevo valor"><select value={v.value} onChange={e=>update('value',e.target.value)}>{choices.filter((x:Row)=>x.active!==0).map((x:Row)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="Mes inicial"><input type="month" required value={v.start_month} onChange={e=>update('start_month',e.target.value)}/></Field><Field label="Último mes vigente" hint="Opcional para responsabilidades continuas. Ambos extremos son inclusivos."><input type="month" min={v.start_month} required={v.kind==='preaching'&&!!t?.requires_campaign} value={v.end_month} onChange={e=>update('end_month',e.target.value)}/></Field>{v.kind==='preaching'&&!!t?.requires_campaign&&<Field label="Campaña"><select required value={v.campaign_id} onChange={e=>update('campaign_id',e.target.value)}><option value="">Selecciona una campaña</option>{data.campaigns.filter((c:Row)=>c.active&&c.type_id===v.value).map((c:Row)=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field>}<div className="span-two"><Field label="Motivo u observación"><textarea rows={3} required value={v.notes} onChange={e=>update('notes',e.target.value)}/></Field></div></div><div className="notice"><Info size={16}/><span>Si existe una asignación anterior abierta, se cierra en el mes previo. Los informes ya registrados conservan su clasificación hasta una corrección autorizada.</span></div><div className="dialog-actions"><Button onClick={()=>setDialog(null)}>Cancelar</Button><Button primary type="submit" disabled={busy}>Guardar vigencia</Button></div></form>;}

function ReportForm(){const{data,dialog:d,mutate,setDialog,busy}=useApp();const r=d.report,[v,setV]=useState<Row>({...r,...d.initial,reason:d.initial?.reason||'',resolveQuality:!!d.issue});const t=data.types.find((t:Row)=>t.id===v.type_id),counts=v.type_id===r.type_id?!!r.counts_hours:!!t?.counts_hours;const update=(key:string,value:any)=>setV(s=>({...s,[key]:value}));return <form onSubmit={async e=>{e.preventDefault();try{await mutate({action:'report',data:{...v,submit:true,hours:counts?v.hours:null}});if(d.issue)await mutate({action:'resolve',entity:'issue',id:d.issue.id,version:d.issue.version,reason:v.reason},'Revisión resuelta');setDialog(null);}catch{}}}><div className="note-block"><strong>{d.person.alias}</strong><p>{monthName(r.month)} · La corrección quedará registrada con su motivo.</p></div><div className="form-grid"><Field label="Participación"><select value={v.participation??''} onChange={e=>update('participation',e.target.value||null)} required><option value="">Sin registrar</option><option value="SI">Sí</option><option value="NO">No</option></select></Field><Field label="Tipo de predicación del informe"><select value={v.type_id} onChange={e=>update('type_id',e.target.value)}>{data.types.map((t:Row)=><option key={t.id} value={t.id}>{t.name}</option>)}</select></Field><Field label="Horas"><input disabled={!counts} type="number" min="0" step="0.25" value={counts?v.hours??'':''} placeholder={counts?'Sin dato':'No aplica'} onChange={e=>update('hours',e.target.value===''?null:Number(e.target.value))}/></Field><Field label="Cursos bíblicos"><input type="number" min="0" value={v.courses??''} onChange={e=>update('courses',e.target.value===''?null:Number(e.target.value))}/></Field><div className="span-two"><Field label="Comentarios"><textarea rows={4} value={v.comment||''} onChange={e=>update('comment',e.target.value)}/></Field></div><div className="span-two"><Field label="Motivo de la corrección"><textarea required rows={2} value={v.reason} onChange={e=>update('reason',e.target.value)}/></Field></div></div>{parseJSON<string[]>(r.quality,[]).length>0&&<label className="checkbox-label"><input type="checkbox" checked={v.resolveQuality} onChange={e=>update('resolveQuality',e.target.checked)}/> He revisado y confirmo también las observaciones de calidad de este informe.</label>}<div className="dialog-actions"><Button onClick={()=>setDialog(null)}>Cancelar</Button><Button primary type="submit" disabled={busy}>Guardar corrección</Button></div></form>;}

function ActionForm(){const{dialog:d,setDialog,mutate,busy}=useApp();const[reason,setReason]=useState(''),[end,setEnd]=useState(currentMonth()),[field,setField]=useState('Informe');const submit=async(e:React.FormEvent)=>{e.preventDefault();try{if(d.kind==='period')await mutate({action:'period',month:d.month,state:d.period?.state==='closed'?'open':'closed',version:d.period?.version,reason});else if(d.kind==='closeHistory')await mutate({action:'closeHistory',id:d.history.id,version:d.history.version,end_month:end,reason});else if(d.kind==='correction')await mutate({action:'correction',data:{report_id:d.report.id,field,message:reason}},'Solicitud de corrección registrada');setDialog(null);}catch{}};return <form onSubmit={submit}>{d.kind==='period'&&<div className="note-block">{monthName(d.month)}. {d.period?.state==='closed'?'La reapertura permitirá registrar y corregir informes.':'Los informes quedarán protegidos contra modificaciones hasta que se reabra el período.'}</div>}{d.kind==='closeHistory'&&<Field label="Último mes vigente"><input type="month" required min={d.history.start_month} value={end} onChange={e=>setEnd(e.target.value)}/></Field>}{d.kind==='correction'&&<><div className="note-block"><strong>{d.person.alias}</strong><p>{monthName(d.report.month)}</p></div><Field label="Campo observado"><select value={field} onChange={e=>setField(e.target.value)}>{['Informe','Participación','Horas','Cursos bíblicos','Comentarios','Tipo de predicación'].map(f=><option key={f}>{f}</option>)}</select></Field></>}<Field label={d.kind==='correction'?'Describe el cambio que se necesita':'Motivo de la operación'}><textarea rows={4} required value={reason} onChange={e=>setReason(e.target.value)}/></Field><div className="dialog-actions"><Button onClick={()=>setDialog(null)}>Cancelar</Button><Button primary type="submit" disabled={busy}>{d.kind==='correction'?'Enviar solicitud':'Confirmar'}</Button></div></form>;}
function IssueDetail(){const{data,dialog:d,setDialog,mutate,busy}=useApp();const[reason,setReason]=useState('');const issue=d.issue,details=parseJSON<Row>(issue.details,{}),report=data.reports.find((r:Row)=>r.publisher_id===issue.publisher_id&&r.month===issue.month);return <><div className="note-block"><strong>{d.person?.alias||'Revisión general'}</strong><p>{issue.message}</p><Badge tone={issue.state==='pending'?'amber':'green'}>{issue.state==='pending'?'Pendiente':'Resuelta'}</Badge></div>{details.alternatives?<><h3>Versiones encontradas en el archivo</h3>{details.alternatives.map((a:Row,i:number)=><div className="alternative" key={i}><strong>Versión {i+1}</strong><p>Participación: {a.participation} · Horas: {a.hours??'Sin dato'} · Cursos: {a.courses??'Sin dato'} · {a.type_id}</p><p>{a.comment||'Sin comentarios'}</p>{report&&issue.state==='pending'&&<Button small onClick={()=>setDialog({kind:'report',person:d.person,report,initial:{...a,id:report.id,version:report.version,reason:`Revisión de duplicado: seleccionada versión ${i+1}.`},issue})}>Revisar y usar esta versión</Button>}</div>)}</>:issue.details&&<div className="details-values">{Object.entries(details).map(([key,value])=><div key={key}><small>{key}</small><span>{typeof value==='object'?JSON.stringify(value):String(value??'Sin dato')}</span></div>)}</div>}{d.person&&<div className="section-actions"><Button small onClick={()=>setDialog({kind:'form',entity:'publisher',data:d.person})}><Pencil size={14}/> Revisar datos del publicador</Button>{report&&<Button small onClick={()=>setDialog({kind:'report',person:d.person,report})}>Corregir informe</Button>}</div>}{issue.state==='pending'&&<form onSubmit={async e=>{e.preventDefault();try{await mutate({action:'resolve',entity:d.entity,id:issue.id,version:issue.version,reason},'Revisión resuelta');setDialog(null);}catch{}}}><Field label="Solución aplicada o motivo de validación"><textarea required rows={3} value={reason} onChange={e=>setReason(e.target.value)}/></Field><div className="dialog-actions"><Button primary type="submit" disabled={busy}>Marcar como resuelta</Button></div></form>}</>;}
function AuditDetail(){const{dialog:d}=useApp();const a=d.entry;return <><div className="note-block"><strong>{a.action}</strong><p>{a.actor} · {new Date(a.at).toLocaleString('es-PE')}</p><p>{a.reason||'Sin motivo adicional'}</p></div><h3>Antes</h3><pre className="json-view">{JSON.stringify(parseJSON(a.before_json,null),null,2)}</pre><h3>Después</h3><pre className="json-view">{JSON.stringify(parseJSON(a.after_json,null),null,2)}</pre></>;}
function Preview(){const{dialog:d,request}=useApp();const[url,setUrl]=useState(''),[error,setError]=useState('');useEffect(()=>{let cancelled=false,bloburl='';(async()=>{try{const result=await request({action:'export',ids:[d.person.id],years:d.years,cutoff:d.cutoff}),pdf=await generateS21(d.person,result.data,d.years,d.cutoff);bloburl=URL.createObjectURL(new Blob([pdf.bytes as BlobPart],{type:'application/pdf'}));if(!cancelled)setUrl(bloburl);}catch(e:any){if(!cancelled)setError(e.message);}})();return()=>{cancelled=true;if(bloburl)URL.revokeObjectURL(bloburl);};},[d.person.id,d.years,d.cutoff,request]);return <>{error?<div className="notice error">{error}</div>:url?<><iframe title={`S-21 de ${d.person.alias}`} src={url}/><div className="dialog-actions"><a className="button primary" href={url} download={`${d.person.alias}.pdf`}><Download size={16}/> Descargar PDF</a></div></>:<div className="empty"><LoaderCircle className="spin"/><p>Preparando el registro de {d.person.alias}…</p></div>}</>;}
